#!/usr/bin/env python3
"""
Fetch USGS daily streamflow data and NWS flood thresholds for Michigan stations,
then determine which stations experienced flooding during April 1-7, 2025.

Uses NWS NWPS API for flood thresholds and USGS daily values for observations.
"""

import csv
import json
import os
import sys
import time
import urllib.request
import urllib.error

# Read station IDs
with open("/root/data/michigan_stations.txt") as f:
    station_ids = [line.strip() for line in f if line.strip()]

print(f"Total stations to process: {len(station_ids)}")

# Step 1: Fetch daily mean discharge (00060) and gage height (00065) from USGS
stations_str = ",".join(station_ids)

# Try fetching both parameters at once
url = (
    f"https://waterservices.usgs.gov/nwis/dv/"
    f"?format=json"
    f"&sites={stations_str}"
    f"&startDT=2025-04-01"
    f"&endDT=2025-04-07"
    f"&parameterCd=00060,00065"
    f"&statCd=00003"
    f"&siteStatus=all"
)

print("Fetching daily values (discharge + gage height) from USGS...")
req = urllib.request.Request(url, headers={"User-Agent": "FloodAnalysis/1.0"})
with urllib.request.urlopen(req, timeout=120) as resp:
    all_data = json.loads(resp.read().decode())

station_discharge = {}  # site -> [(date, value)]
station_gage_height = {}  # site -> [(date, value)]

if "value" in all_data and "timeSeries" in all_data["value"]:
    for ts in all_data["value"]["timeSeries"]:
        site_code = ts["sourceInfo"]["siteCode"][0]["value"]
        var_code = ts["variable"]["variableCode"][0]["value"]
        values = []
        for val_set in ts["values"]:
            for v in val_set["value"]:
                date_str = v["dateTime"][:10]
                raw_val = v["value"]
                # USGS uses -999999 or similar for missing data
                try:
                    fval = float(raw_val)
                    if fval >= 0:  # valid positive measurement
                        values.append((date_str, fval))
                except (ValueError, TypeError):
                    pass
        if values:
            if var_code == "00060":
                station_discharge[site_code] = values
            elif var_code == "00065":
                station_gage_height[site_code] = values

print(f"Got discharge data for {len(station_discharge)} stations")
print(f"Got gage height data for {len(station_gage_height)} stations")

# Step 2: Fetch flood thresholds from NWS NWPS API
# The NWS provides gauges with flood stages. We query by USGS site code.
print("\nFetching flood thresholds from NWS API...")
flood_thresholds = {}  # site_id -> flood_stage (gage height in feet)
action_thresholds = {}  # site_id -> action_stage

for i, sid in enumerate(station_ids):
    try:
        nws_url = f"https://api.water.noaa.gov/nwps/v1/gauges?usgsSiteCode={sid}"
        req = urllib.request.Request(nws_url, headers={
            "User-Agent": "FloodAnalysis/1.0",
            "Accept": "application/json"
        })
        with urllib.request.urlopen(req, timeout=30) as resp:
            nws_data = json.loads(resp.read().decode())

        # Parse the response - it should contain gauge info with flood categories
        if isinstance(nws_data, dict) and "gauges" in nws_data:
            for gauge in nws_data["gauges"]:
                flood_val = gauge.get("flood")
                action_val = gauge.get("action")
                moderate_val = gauge.get("moderate")

                # Try to get flood stage from various fields
                if flood_val is not None:
                    try:
                        flood_thresholds[sid] = float(flood_val)
                        print(f"  {sid}: flood_stage={flood_val}")
                    except (ValueError, TypeError):
                        pass
                if action_val is not None:
                    try:
                        action_thresholds[sid] = float(action_val)
                    except (ValueError, TypeError):
                        pass
        elif isinstance(nws_data, list):
            for gauge in nws_data:
                flood_val = gauge.get("flood") or gauge.get("floodStage")
                action_val = gauge.get("action") or gauge.get("actionStage")
                if flood_val is not None:
                    try:
                        flood_thresholds[sid] = float(flood_val)
                        print(f"  {sid}: flood_stage={flood_val}")
                    except (ValueError, TypeError):
                        pass
                if action_val is not None:
                    try:
                        action_thresholds[sid] = float(action_val)
                    except (ValueError, TypeError):
                        pass

    except urllib.error.HTTPError as e:
        if e.code == 404:
            pass  # No NWS gauge for this USGS site
        else:
            print(f"  {sid}: HTTP {e.code}")
    except Exception as e:
        print(f"  {sid}: Error: {e}")

    if (i + 1) % 10 == 0:
        print(f"  Processed {i+1}/{len(station_ids)} stations...")
    time.sleep(0.3)  # Be polite to the API

print(f"\nGot flood thresholds for {len(flood_thresholds)} stations")
print(f"Got action thresholds for {len(action_thresholds)} stations")

# Debug: let's look at a sample NWS response to understand the structure
print("\nSample NWS response for debugging:")
for sid in station_ids[:3]:
    try:
        nws_url = f"https://api.water.noaa.gov/nwps/v1/gauges?usgsSiteCode={sid}"
        req = urllib.request.Request(nws_url, headers={
            "User-Agent": "FloodAnalysis/1.0",
            "Accept": "application/json"
        })
        with urllib.request.urlopen(req, timeout=30) as resp:
            nws_data = json.loads(resp.read().decode())
        print(f"\n  Station {sid}:")
        print(f"  {json.dumps(nws_data, indent=2)[:1000]}")
        break  # Just need one sample
    except Exception as e:
        print(f"  {sid}: {e}")

# Step 3: Determine flooding
print("\n--- Determining flood days ---")
results = {}

for sid in station_ids:
    if sid in flood_thresholds:
        fs = flood_thresholds[sid]
        flood_days = 0

        # Prefer gage height comparison
        if sid in station_gage_height:
            for date_str, gh in station_gage_height[sid]:
                if gh >= fs:
                    flood_days += 1
                    print(f"  {sid}: {date_str} GH={gh:.2f} >= flood_stage={fs:.2f} -> FLOOD")

        if flood_days > 0:
            results[sid] = flood_days

print(f"\nStations with at least one flood day: {len(results)}")

# Write results
os.makedirs("/root/output", exist_ok=True)
with open("/root/output/flood_results.csv", "w", newline="") as f:
    writer = csv.writer(f)
    writer.writerow(["station_id", "flood_days"])
    for sid in sorted(results.keys()):
        writer.writerow([sid, results[sid]])

print(f"Results written to /root/output/flood_results.csv")

