#!/usr/bin/env python3
"""
Fetch flood thresholds and streamflow data for Michigan USGS stations.
Determine flooding during April 1-7, 2025.

Strategy:
1. Get flood thresholds from NWS NWPS API (all gauges in Michigan at once)
2. Get daily discharge and gage height from USGS
3. Compare gage height to flood stage
"""

import csv
import json
import os
import sys
import time
import urllib.request
import urllib.error

# Read station IDs
with open("/root/data/michigan_stations.txt") as f:
    station_ids = [line.strip() for line in f if line.strip()]

print(f"Total stations: {len(station_ids)}")
station_set = set(station_ids)

# ============================================================
# Step 1: Get flood thresholds
# ============================================================

# Try getting all Michigan gauges from NWS NWPS API at once
# The NWPS API allows querying by state
print("Fetching NWS gauges for Michigan (state=MI)...")
flood_thresholds = {}  # usgs_site_id -> flood_stage_ft

try:
    nws_url = "https://api.water.noaa.gov/nwps/v1/gauges?stateCodes=MI"
    req = urllib.request.Request(nws_url, headers={
        "User-Agent": "FloodAnalysis/1.0",
        "Accept": "application/json"
    })
    with urllib.request.urlopen(req, timeout=120) as resp:
        raw = resp.read().decode()

    nws_data = json.loads(raw)

    # Save raw response for debugging
    with open("/tmp/nws_mi_gauges.json", "w") as f:
        f.write(raw[:50000])

    print(f"NWS response type: {type(nws_data)}")
    if isinstance(nws_data, dict):
        print(f"NWS response keys: {list(nws_data.keys())[:20]}")
        # Try various structures
        gauges = nws_data.get("gauges", nws_data.get("data", nws_data.get("features", [])))
        if not gauges and len(nws_data) < 20:
            for k, v in nws_data.items():
                print(f"  Key '{k}': type={type(v)}, preview={str(v)[:200]}")
    elif isinstance(nws_data, list):
        gauges = nws_data
        print(f"NWS returned list with {len(gauges)} items")
    else:
        gauges = []

    if gauges:
        sample = gauges[0] if gauges else {}
        print(f"Sample gauge keys: {list(sample.keys()) if isinstance(sample, dict) else 'N/A'}")
        print(f"Sample gauge: {json.dumps(sample, indent=2)[:800]}")

    for gauge in gauges:
        if not isinstance(gauge, dict):
            continue
        # Find USGS site code - could be in various fields
        usgs_id = (gauge.get("usgsSiteCode") or gauge.get("usgs_site_code") or
                   gauge.get("usgsSiteId") or gauge.get("usgsId") or "")
        lid = gauge.get("lid", gauge.get("gaugeId", gauge.get("id", "")))

        if not usgs_id:
            # Maybe it's nested
            if "siteCode" in gauge:
                usgs_id = gauge["siteCode"]

        # Get flood stage
        flood_stage = None
        # Try direct fields
        for key in ["flood", "floodStage", "flood_stage", "floodFlow"]:
            if key in gauge and gauge[key] is not None:
                try:
                    flood_stage = float(gauge[key])
                    break
                except (ValueError, TypeError):
                    pass

        # Try nested in "floodCategories" or "categories"
        if flood_stage is None:
            cats = gauge.get("floodCategories", gauge.get("categories", {}))
            if isinstance(cats, dict):
                for key in ["flood", "floodStage", "minor", "minorFlood"]:
                    if key in cats and cats[key] is not None:
                        try:
                            flood_stage = float(cats[key])
                            break
                        except (ValueError, TypeError):
                            pass

        if usgs_id and flood_stage is not None and usgs_id in station_set:
            flood_thresholds[usgs_id] = flood_stage
            print(f"  Matched: USGS {usgs_id} (NWS LID: {lid}), flood_stage={flood_stage}")

    print(f"\nMatched flood thresholds for {len(flood_thresholds)} of our stations")

except Exception as e:
    print(f"NWS state query failed: {e}")
    import traceback
    traceback.print_exc()

# If state query didn't work, try getting all gauges
if len(flood_thresholds) == 0:
    print("\nTrying NWS NWPS v1 gauges endpoint without state filter...")
    try:
        nws_url = "https://api.water.noaa.gov/nwps/v1/gauges"
        req = urllib.request.Request(nws_url, headers={
            "User-Agent": "FloodAnalysis/1.0",
            "Accept": "application/json"
        })
        with urllib.request.urlopen(req, timeout=120) as resp:
            raw = resp.read().decode()
        with open("/tmp/nws_all_gauges_sample.json", "w") as f:
            f.write(raw[:100000])
        print(f"Response length: {len(raw)}")
        print(f"First 2000 chars: {raw[:2000]}")
    except Exception as e:
        print(f"  Failed: {e}")

# ============================================================
# Step 2: Also try individual NWS gauge lookups with proper rate limiting
# ============================================================
if len(flood_thresholds) < 10:
    print("\nTrying individual NWS gauge lookups with longer delays...")
    for sid in station_ids:
        if sid in flood_thresholds:
            continue
        try:
            # Try the direct gauge endpoint with USGS site code
            nws_url = f"https://api.water.noaa.gov/nwps/v1/gauges?usgsSiteCode={sid}"
            req = urllib.request.Request(nws_url, headers={
                "User-Agent": "FloodAnalysis/1.0",
                "Accept": "application/json"
            })
            with urllib.request.urlopen(req, timeout=60) as resp:
                data = json.loads(resp.read().decode())

            if isinstance(data, dict) and "gauges" in data:
                for g in data["gauges"]:
                    fs = None
                    for key in ["flood", "floodStage", "flood_stage"]:
                        if key in g and g[key] is not None:
                            try:
                                fs = float(g[key])
                                break
                            except:
                                pass
                    if fs is not None:
                        flood_thresholds[sid] = fs
                        print(f"  {sid}: flood_stage={fs}")
            elif isinstance(data, list):
                for g in data:
                    fs = None
                    for key in ["flood", "floodStage", "flood_stage"]:
                        if key in g and g[key] is not None:
                            try:
                                fs = float(g[key])
                                break
                            except:
                                pass
                    if fs is not None:
                        flood_thresholds[sid] = fs
                        print(f"  {sid}: flood_stage={fs}")

            time.sleep(2)  # Longer delay to avoid rate limiting
        except urllib.error.HTTPError as e:
            if e.code == 429:
                print(f"  {sid}: Rate limited, waiting 10s...")
                time.sleep(10)
            elif e.code == 404:
                pass
            else:
                print(f"  {sid}: HTTP {e.code}")
                time.sleep(2)
        except Exception as e:
            print(f"  {sid}: {e}")
            time.sleep(2)

print(f"\nTotal flood thresholds obtained: {len(flood_thresholds)}")

# ============================================================
# Step 3: Get USGS data
# ============================================================
stations_str = ",".join(station_ids)

print("\nFetching daily values from USGS (discharge + gage height)...")
url = (
    f"https://waterservices.usgs.gov/nwis/dv/"
    f"?format=json"
    f"&sites={stations_str}"
    f"&startDT=2025-04-01"
    f"&endDT=2025-04-07"
    f"&parameterCd=00060,00065"
    f"&statCd=00003"
    f"&siteStatus=all"
)
req = urllib.request.Request(url, headers={"User-Agent": "FloodAnalysis/1.0"})
with urllib.request.urlopen(req, timeout=120) as resp:
    usgs_data = json.loads(resp.read().decode())

station_discharge = {}
station_gage_height = {}

if "value" in usgs_data and "timeSeries" in usgs_data["value"]:
    for ts in usgs_data["value"]["timeSeries"]:
        site_code = ts["sourceInfo"]["siteCode"][0]["value"]
        var_code = ts["variable"]["variableCode"][0]["value"]
        values = []
        for val_set in ts["values"]:
            for v in val_set["value"]:
                date_str = v["dateTime"][:10]
                raw_val = v["value"]
                try:
                    fval = float(raw_val)
                    if fval >= 0:
                        values.append((date_str, fval))
                except (ValueError, TypeError):
                    pass
        if values:
            if var_code == "00060":
                station_discharge[site_code] = values
            elif var_code == "00065":
                station_gage_height[site_code] = values

print(f"Discharge data: {len(station_discharge)} stations")
print(f"Gage height data: {len(station_gage_height)} stations")

# Debug: check what parameters are available
print("\nAll variable codes in response:")
if "value" in usgs_data and "timeSeries" in usgs_data["value"]:
    var_codes_seen = set()
    for ts in usgs_data["value"]["timeSeries"]:
        vc = ts["variable"]["variableCode"][0]["value"]
        vn = ts["variable"]["variableName"]
        var_codes_seen.add((vc, vn))
    for vc, vn in sorted(var_codes_seen):
        print(f"  {vc}: {vn}")

# ============================================================
# Step 4: Try to also get instantaneous values (gage height might only be in IV)
# ============================================================
if len(station_gage_height) == 0:
    print("\nGage height not in daily values. Trying instantaneous values (IV)...")
    # IV service can return a lot of data; let's just request gage height
    url_iv = (
        f"https://waterservices.usgs.gov/nwis/iv/"
        f"?format=json"
        f"&sites={stations_str}"
        f"&startDT=2025-04-01"
        f"&endDT=2025-04-07"
        f"&parameterCd=00065"
        f"&siteStatus=all"
    )
    try:
        req = urllib.request.Request(url_iv, headers={"User-Agent": "FloodAnalysis/1.0"})
        with urllib.request.urlopen(req, timeout=120) as resp:
            iv_data = json.loads(resp.read().decode())

        # For IV data, compute daily max gage height
        if "value" in iv_data and "timeSeries" in iv_data["value"]:
            for ts in iv_data["value"]["timeSeries"]:
                site_code = ts["sourceInfo"]["siteCode"][0]["value"]
                daily_max = {}  # date -> max gage height
                for val_set in ts["values"]:
                    for v in val_set["value"]:
                        date_str = v["dateTime"][:10]
                        try:
                            fval = float(v["value"])
                            if fval >= 0:
                                if date_str not in daily_max or fval > daily_max[date_str]:
                                    daily_max[date_str] = fval
                        except (ValueError, TypeError):
                            pass
                if daily_max:
                    station_gage_height[site_code] = [(d, v) for d, v in sorted(daily_max.items())]

        print(f"Got IV gage height data for {len(station_gage_height)} stations")
    except Exception as e:
        print(f"IV fetch failed: {e}")

# ============================================================
# Step 5: Determine flooding
# ============================================================
print("\n===== Determining flood days =====")
results = {}

for sid in station_ids:
    if sid not in flood_thresholds:
        continue
    fs = flood_thresholds[sid]
    flood_days = 0

    if sid in station_gage_height:
        for date_str, gh in station_gage_height[sid]:
            if gh >= fs:
                flood_days += 1
                print(f"  FLOOD: {sid} on {date_str}: GH={gh:.2f} >= flood_stage={fs:.2f}")

    if flood_days > 0:
        results[sid] = flood_days

print(f"\nStations with at least one flood day: {len(results)}")
for sid, days in sorted(results.items()):
    print(f"  {sid}: {days} flood days")

# Write results
os.makedirs("/root/output", exist_ok=True)
with open("/root/output/flood_results.csv", "w", newline="") as f:
    writer = csv.writer(f)
    writer.writerow(["station_id", "flood_days"])
    for sid in sorted(results.keys()):
        writer.writerow([sid, results[sid]])

print(f"\nResults written to /root/output/flood_results.csv")
